d = json.load(open(base))
rows = {f["id"]: f for s in d["sections"] if s["id"] == "editing" for f in s["features"]}
x = json.load(open(fix))
ids = [u["id"] for u in x["updates"]]
print("rows", len(rows), "updates", len(ids), "unique", len(set(ids)), "remove", len(x["remove"]))
