for u in x["updates"]:
    for k, v in u.items():
        if k != "id" and rows[u["id"]].get(k, "") == v:
            print("no change", u["id"], k)
merged = {i: dict(r) for i, r in rows.items()}
for u in x["updates"]:
    merged[u["id"]].update(u)
for i, r in merged.items():
    if len(r["summary"]) > 140:
        print(len(r["summary"]), i, r["summary"])
bad = ["refuse", "the op", "the core", "answers", "ticks", "patch"]
for i, r in merged.items():
    t = " ".join(str(r.get(k, "")) for k in ("name", "summary", "where"))
    for b in bad:
        if b in t.lower():
            print("word", b, i)
names = {}
for r in merged.values():
    names.setdefault(r["name"], []).append(r["id"])
print("dup names", {k: v for k, v in names.items() if len(v) > 1})

